func (q *Queries) RetimeRecurrenceOverride(ctx context.Context, arg RetimeRecurrenceOverrideParams) error {
	_, err := q.db.ExecContext(ctx, retimeRecurrenceOverride,
		arg.RecurrenceOriginalStart,
		arg.StartAt,
		arg.EndAt,
		arg.ID,
	)
	return err
}

